"""Single-cell ACML real-data/GPU preflight. Does NOT start the research pair.

Includes the verified small code package. Installs/upgrades no libraries.
Downloads the pinned public dataset if needed. Uses one GPU for short diagnostic
trajectories and validation timing. Retains all output and full diagnostic states.
"""
from pathlib import Path
import base64
import hashlib
import io
import json
import os
import subprocess
import sys
import time
import traceback
import uuid
import zipfile

PACKAGE_SHA256 = "3c437b7e71f9bb5eaed522df222a14f55a2bba93377f63d41a51c0f3de53adea"
PACKAGE_BASE64 = """"""


def unpack_package(payload, destination):
    if hashlib.sha256(payload).hexdigest() != PACKAGE_SHA256:
        raise ValueError("Embedded code package checksum failed; stop and use the original script.")
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        if archive.testzip() is not None:
            raise ValueError("Embedded archive integrity check failed.")
        for name in archive.namelist():
            (destination / name).resolve().relative_to(destination.resolve())
        manifest = json.loads(archive.read("ACML_Peak_First_Pair/CHECKSUMS.json"))
        for name, entry in manifest.items():
            data = archive.read("ACML_Peak_First_Pair/" + name)
            if len(data) != entry["bytes"] or hashlib.sha256(data).hexdigest() != entry["sha256"]:
                raise ValueError("Packaged file checksum failed: " + name)
        archive.extractall(destination)
    return destination / "ACML_Peak_First_Pair"


def run_logged(command, cwd, environment, log, label):
    print(label, flush=True)
    started = time.monotonic()
    with log.open("w", encoding="utf-8") as output:
        process = subprocess.Popen(command, cwd=cwd, env=environment,
                                   stdout=output, stderr=subprocess.STDOUT)
        try:
            while True:
                try:
                    code = process.wait(timeout=30)
                    break
                except subprocess.TimeoutExpired:
                    print(f"  Still checking: {(time.monotonic()-started)/60:.1f} minutes. Log: {log.name}", flush=True)
        finally:
            if process.poll() is None:
                process.terminate()
                try:
                    process.wait(timeout=15)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()
    if code != 0:
        tail = log.read_text(encoding="utf-8", errors="replace").splitlines()[-45:]
        print("\n".join(tail), flush=True)
        raise RuntimeError(f"{label} failed (exit {code}). Full log retained at {log}.")
    print(f"  Passed in {(time.monotonic()-started)/60:.1f} minutes.", flush=True)


def run_check():
    working = Path("/kaggle/working")
    if not working.is_dir():
        raise RuntimeError("Run this script in the Kaggle notebook whose initial report you supplied.")
    root = working / ("ACML_preflight_" + time.strftime("%Y%m%d_%H%M%S") + "_" + uuid.uuid4().hex[:6])
    root.mkdir(exist_ok=False)
    summary = {"status": "started", "purpose": "Real-data/model/device compatibility, resume and timing check",
               "research_pair_run": False, "libraries_installed_or_upgraded": False,
               "embedded_package_sha256": PACKAGE_SHA256, "output_folder": str(root)}
    package = None
    started = time.monotonic()
    try:
        package = unpack_package(base64.b64decode(PACKAGE_BASE64), root)
        common = {"OMP_NUM_THREADS": "1", "MKL_NUM_THREADS": "1", "PYTHONDONTWRITEBYTECODE": "1",
                  "CUBLAS_WORKSPACE_CONFIG": ":4096:8", "TOKENIZERS_PARALLELISM": "false",
                  "HF_HOME": str(working / "acml_hf_cache")}
        # Restrict each child process before importing torch. The notebook's
        # already-initialized CUDA context and software installation are untouched.
        cpu_env = dict(os.environ, **common, CUDA_VISIBLE_DEVICES="")
        gpu_env = dict(os.environ, **common, CUDA_VISIBLE_DEVICES="0")
        (root / "execution_settings.json").write_text(json.dumps(
            {"research_and_preflight_environment_overrides": dict(common, CUDA_VISIBLE_DEVICES="0"),
             "note": "Use these same overrides for any later research run or resume."}, indent=2))
        run_logged([sys.executable, "-u", "-B", "check_cpu.py"], package, cpu_env,
                   root / "01_cpu_checks.log", "1/2: Synthetic compatibility checks on Kaggle's installed libraries")
        checks = json.loads((package / "evidence/cpu_test_report.json").read_text())
        if not checks.get("passed") or checks.get("tests") != 21:
            raise RuntimeError("Expected all 21 local compatibility checks to pass.")
        summary["cpu_tests"] = {key: checks[key] for key in ("tests", "passed", "python", "torch", "numpy")}
        run_logged([sys.executable, "-u", "-B", "peak_pair.py", "preflight", "--device", "cuda:0",
                    "--output", str(root / "real_data_check")], package, gpu_env,
                   root / "02_real_data_check.log", "2/2: Pinned dataset, actual medium-4 model, GPU resume and validation timing")
        report = json.loads((root / "real_data_check/preflight.json").read_text())
        if report.get("status") != "passed" or not report.get("resume_probe_exact") or not report.get("first_transition_anchors_match"):
            raise RuntimeError("Real-data preflight did not satisfy all required checks.")
        summary["status"] = "PREFLIGHT_PASSED_REVIEW_COST_AND_SESSION_LIMITS_BEFORE_RESEARCH_RUN"
        summary["preflight"] = report
        projection = report["rough_cost_projection"]
        summary["rough_hours_training_component"] = sum(r["instrumented_training_seconds"] for r in projection.values()) / 3600
        summary["rough_hours_validation_component"] = sum(r["validation_seconds"] for r in projection.values()) / 3600
        summary["cost_limits"] = (
            "These are short-prefix projections, not total runtime guarantees. Training prefix includes dense "
            "displacement instrumentation. Add loading, train-subset/test evaluation, prediction saves and "
            "checkpoint overhead. Account GPU quota and session allowance are not measured here.")
    except BaseException as error:
        summary["status"] = "INTERRUPTED" if isinstance(error, KeyboardInterrupt) else "CHECK_FAILED"
        summary["error_type"] = type(error).__name__
        summary["error"] = str(error)
        (root / "failure_traceback.txt").write_text(traceback.format_exc(), encoding="utf-8")
        print("The check stopped. No research pair was launched. Return the report ZIP below.", flush=True)
    finally:
        summary["elapsed_minutes"] = (time.monotonic() - started) / 60
        (root / "ACML_Kaggle_Preflight_Report.json").write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")
        # Return small evidence only. Full states, vocabulary, dataset/cache and
        # split arrays remain in the output folder, not in this report ZIP.
        files = list(root.glob("*.json")) + list(root.glob("*.log")) + list(root.glob("*.txt"))
        if package is not None:
            files += [p for p in (package / "evidence").glob("cpu_test_*") if p.is_file()]
        for name in ("preflight.json", "protocol.json", "environment.json", "data_manifest.json", "source_hashes.json"):
            path = root / "real_data_check" / name
            if path.is_file():
                files.append(path)
        returned = working / (root.name + "_REPORT.zip")
        with zipfile.ZipFile(returned, "w", zipfile.ZIP_DEFLATED) as archive:
            for path in sorted(set(files)):
                archive.write(path, path.relative_to(root).as_posix())
        print("\nSTATUS:", summary["status"], flush=True)
        if "rough_hours_training_component" in summary:
            print("Approximate training component (both arms):", round(summary["rough_hours_training_component"], 2), "hours")
            print("Approximate validation component (both arms):", round(summary["rough_hours_validation_component"], 2), "hours")
            print("These exclude other costs; send the report before starting the full run.")
        print("SEND BACK:", returned, flush=True)
        print("KEEP the full output folder and acml_hf_cache. Do not delete diagnostic states or logs.", flush=True)
    return summary


if __name__ == "__main__":
    run_check()
